create or replace function public.apply_deposit_promo_atomic(p_user_id uuid,p_deposit_amount numeric,p_deposit_ref text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_claim public.promo_claims%rowtype; v_offer public.promo_offers%rowtype; v_profile public.profiles%rowtype; v_bonus numeric:=0; v_free_rounds integer:=0; v_wager_multiplier numeric:=0; v_wager_required numeric:=0; v_ref text; v_wallet jsonb; begin if p_user_id is null then raise exception 'USER_REQUIRED'; end if; if coalesce(p_deposit_amount,0)<=0 then raise exception 'INVALID_DEPOSIT_AMOUNT'; end if; if nullif(trim(p_deposit_ref),'') is null then raise exception 'DEPOSIT_REF_REQUIRED'; end if; select * into v_profile from public.profiles where id=p_user_id for update; if found and coalesce(v_profile.wager_required,0)>coalesce(v_profile.wager_progress,0) then return jsonb_build_object('ok',false,'error','WAGERING_ALREADY_ACTIVE','source','daily_streak'); end if; select * into v_claim from public.promo_claims where user_id=p_user_id and status='active' order by claimed_at desc limit 1 for update; if not found then return jsonb_build_object('ok',true,'applied',false,'reason','NO_ACTIVE_CLAIM'); end if; select * into v_offer from public.promo_offers where id=v_claim.offer_id for share; if not found or not coalesce(v_offer.active,false) then return jsonb_build_object('ok',false,'error','OFFER_NOT_ACTIVE'); end if; if v_offer.starts_at is not null and v_offer.starts_at>now() then return jsonb_build_object('ok',false,'error','OFFER_NOT_STARTED'); end if; if v_offer.ends_at is not null and v_offer.ends_at<=now() then return jsonb_build_object('ok',false,'error','OFFER_EXPIRED'); end if; if v_claim.expires_at is not null and v_claim.expires_at<=now() then update public.promo_claims set status='expired',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('expired_at',now()) where id=v_claim.id; return jsonb_build_object('ok',false,'error','CLAIM_EXPIRED'); end if; if p_deposit_amount<coalesce(v_offer.min_deposit,0) then return jsonb_build_object('ok',true,'applied',false,'reason','MIN_DEPOSIT_NOT_MET','minimum',coalesce(v_offer.min_deposit,0)); end if; v_bonus:=round(least(case when coalesce(v_offer.max_bonus,0)>0 then v_offer.max_bonus else p_deposit_amount*coalesce(v_offer.bonus_percent,0)/100 end,p_deposit_amount*coalesce(v_offer.bonus_percent,0)/100),2); v_bonus:=greatest(coalesce(v_bonus,0),0); v_free_rounds:=greatest(coalesce(v_offer.free_rounds,0),0); v_wager_multiplier:=greatest(coalesce(v_offer.wagering_multiplier,0),0); v_wager_required:=round(v_bonus*v_wager_multiplier,2); v_ref:='promo:'||v_claim.id::text||':deposit:'||trim(p_deposit_ref); if v_bonus>0 then v_wallet:=public.wallet_apply_delta(p_user_id=>p_user_id,p_delta_balance=>0,p_delta_bonus=>v_bonus,p_delta_locked=>0,p_reason=>'promo_bonus',p_ref_id=>v_ref,p_method=>'manual',p_metadata=>jsonb_build_object('promo_claim_id',v_claim.id,'promo_offer_id',v_offer.id,'promo_slug',v_offer.slug,'deposit_ref',p_deposit_ref,'deposit_amount',p_deposit_amount,'wager_required',v_wager_required)); if coalesce(v_wallet->>'ok','false')<>'true' then raise exception 'PROMO_WALLET_APPLY_FAILED'; end if; end if; if v_free_rounds>0 then insert into public.free_round_entitlements(user_id,game,remaining,source,expires_at,metadata,ref_id) values(p_user_id,'crash',v_free_rounds,'promo',v_offer.ends_at,jsonb_build_object('promo_claim_id',v_claim.id,'promo_offer_id',v_offer.id,'deposit_ref',p_deposit_ref),v_ref||':free_rounds') on conflict (ref_id) where ref_id is not null do nothing; end if; update public.promo_claims set status=case when v_wager_required>0 then 'applied' else 'completed' end,bonus_awarded=v_bonus,free_rounds_awarded=v_free_rounds,wagering_required=v_wager_required,wagering_progress=0,metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('applied_at',now(),'deposit_ref',p_deposit_ref,'ref_id',v_ref,'reward_atomic',true) where id=v_claim.id; return jsonb_build_object('ok',true,'applied',(v_bonus>0 or v_free_rounds>0),'claim_id',v_claim.id,'offer_id',v_offer.id,'offer_slug',v_offer.slug,'bonus_awarded',v_bonus,'free_rounds_awarded',v_free_rounds,'wagering_required',v_wager_required,'wallet',v_wallet); end; $$;
create or replace function public.credit_affiliate_first_deposit_atomic(p_user_id uuid,p_deposit_amount numeric,p_intent_id text,p_reward numeric default 20,p_minimum numeric default 50) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_referral public.affiliate_referrals%rowtype; v_affiliate_user_id uuid; v_ref text; v_wallet jsonb; begin if p_user_id is null then raise exception 'USER_REQUIRED'; end if; if coalesce(p_deposit_amount,0)<=0 then raise exception 'INVALID_DEPOSIT_AMOUNT'; end if; if nullif(trim(p_intent_id),'') is null then raise exception 'INTENT_ID_REQUIRED'; end if; if coalesce(p_reward,0)<=0 or p_deposit_amount<coalesce(p_minimum,0) then return jsonb_build_object('ok',true,'credited',false,'reason','NOT_ELIGIBLE'); end if; select * into v_referral from public.affiliate_referrals where referred_user_id=p_user_id order by created_at asc limit 1 for update; if not found then return jsonb_build_object('ok',true,'credited',false,'reason','NO_REFERRAL'); end if; if v_referral.status not in ('tracked','registered') then return jsonb_build_object('ok',true,'credited',false,'idempotent',true,'reason','ALREADY_PROCESSED','status',v_referral.status); end if; v_affiliate_user_id:=coalesce(v_referral.affiliate_user_id,v_referral.referrer_id); if v_affiliate_user_id is null then return jsonb_build_object('ok',false,'error','AFFILIATE_USER_MISSING'); end if; v_ref:='aff_firstdep:'||trim(p_intent_id); perform pg_advisory_xact_lock(hashtextextended(v_ref,0)); if exists(select 1 from public.affiliate_commissions where ref_id=v_ref) then return jsonb_build_object('ok',true,'credited',true,'idempotent',true,'ref_id',v_ref); end if; insert into public.affiliate_commissions(affiliate_user_id,referred_user_id,amount,reason,ref_id,status,metadata) values(v_affiliate_user_id,p_user_id,round(p_reward,2),'first_deposit_bonus',v_ref,'pending',jsonb_build_object('deposit_amount',p_deposit_amount,'intent_id',p_intent_id)); v_wallet:=public.wallet_apply_delta(p_user_id=>v_affiliate_user_id,p_delta_balance=>round(p_reward,2),p_delta_bonus=>0,p_delta_locked=>0,p_reason=>'affiliate_first_deposit',p_ref_id=>v_ref,p_method=>'internal_game',p_metadata=>jsonb_build_object('referred_user_id',p_user_id,'intent_id',p_intent_id)); if coalesce(v_wallet->>'ok','false')<>'true' then raise exception 'AFFILIATE_WALLET_APPLY_FAILED'; end if; update public.affiliate_commissions set status='credited',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('credited_at',now()) where ref_id=v_ref; update public.affiliate_referrals set status='first_deposit',first_deposit_amount=p_deposit_amount,first_deposit_at=now(),total_deposited=coalesce(total_deposited,0)+p_deposit_amount,total_commission=coalesce(total_commission,0)+round(p_reward,2),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('first_deposit_intent_id',p_intent_id,'first_deposit_reward',round(p_reward,2)) where id=v_referral.id; return jsonb_build_object('ok',true,'credited',true,'idempotent',false,'affiliate_user_id',v_affiliate_user_id,'amount',round(p_reward,2),'ref_id',v_ref,'wallet',v_wallet); end; $$;
create or replace function public.credit_deposit_atomic(p_intent_id text,p_provider text,p_external_id text,p_user_id uuid,p_amount numeric,p_currency text,p_provider_payload jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_intent public.deposit_intents%rowtype; v_wallet jsonb; v_promo jsonb; v_affiliate jsonb; v_ref text; begin if nullif(trim(p_intent_id),'') is null then raise exception 'INTENT_ID_REQUIRED'; end if; if nullif(trim(p_provider),'') is null then raise exception 'PROVIDER_REQUIRED'; end if; if p_user_id is null then raise exception 'USER_REQUIRED'; end if; if coalesce(p_amount,0)<=0 then raise exception 'INVALID_AMOUNT'; end if; if upper(coalesce(p_currency,''))<>'MXN' then raise exception 'CURRENCY_MISMATCH'; end if; perform pg_advisory_xact_lock(hashtextextended('deposit:'||trim(p_intent_id),0)); select * into v_intent from public.deposit_intents where intent_id=trim(p_intent_id) for update; if not found then raise exception 'DEPOSIT_INTENT_NOT_FOUND'; end if; if v_intent.user_id<>p_user_id then raise exception 'DEPOSIT_USER_MISMATCH'; end if; if lower(v_intent.provider)<>lower(trim(p_provider)) then raise exception 'DEPOSIT_PROVIDER_MISMATCH'; end if; if upper(coalesce(v_intent.currency,'MXN'))<>upper(p_currency) then raise exception 'DEPOSIT_CURRENCY_MISMATCH'; end if; if abs(v_intent.amount-p_amount)>0.01 then raise exception 'DEPOSIT_AMOUNT_MISMATCH'; end if; if v_intent.status='credited' then return jsonb_build_object('ok',true,'credited',true,'idempotent',true,'intent_id',v_intent.intent_id,'external_id',v_intent.external_id); end if; if v_intent.status in ('failed','cancelled','canceled','rejected') then raise exception 'DEPOSIT_INTENT_FINAL'; end if; v_ref:=lower(trim(p_provider))||'_deposit:'||trim(p_intent_id); v_wallet:=public.wallet_apply_delta(p_user_id=>p_user_id,p_delta_balance=>round(p_amount,2),p_delta_bonus=>0,p_delta_locked=>0,p_reason=>'deposit_'||lower(trim(p_provider)),p_ref_id=>v_ref,p_method=>case when lower(trim(p_provider)) in ('mercadopago','stripe') then 'card' else 'manual' end,p_metadata=>jsonb_build_object('external_id',p_external_id,'intent_id',p_intent_id,'provider',lower(trim(p_provider)),'currency',upper(p_currency))||coalesce(p_provider_payload,'{}'::jsonb)); if coalesce(v_wallet->>'ok','false')<>'true' then raise exception 'DEPOSIT_WALLET_APPLY_FAILED'; end if; v_promo:=public.apply_deposit_promo_atomic(p_user_id,p_amount,p_intent_id); if coalesce(v_promo->>'ok','true')<>'true' and coalesce(v_promo->>'error','')<>'WAGERING_ALREADY_ACTIVE' then raise exception 'DEPOSIT_PROMO_APPLY_FAILED'; end if; v_affiliate:=public.credit_affiliate_first_deposit_atomic(p_user_id,p_amount,p_intent_id,20,50); if coalesce(v_affiliate->>'ok','true')<>'true' then raise exception 'DEPOSIT_AFFILIATE_APPLY_FAILED'; end if; update public.deposit_intents set status='credited',external_id=coalesce(nullif(trim(p_external_id),''),external_id),provider_payload=coalesce(provider_payload,'{}'::jsonb)||coalesce(p_provider_payload,'{}'::jsonb),bonus_applied=coalesce((v_promo->>'applied')::boolean,false),free_spins_awarded=coalesce((v_promo->>'free_rounds_awarded')::integer,0),updated_at=now() where id=v_intent.id; update public.profiles set last_deposit_amount=p_amount,last_deposit_at=now(),updated_at=now() where id=p_user_id; return jsonb_build_object('ok',true,'credited',true,'idempotent',coalesce((v_wallet->>'idempotent')::boolean,false),'intent_id',p_intent_id,'external_id',p_external_id,'amount',round(p_amount,2),'wallet',v_wallet,'promo',v_promo,'affiliate',v_affiliate); end; $$;
